const buffer = await this.helpers.getBinaryDataBuffer($itemIndex, key);
const base64 = buffer.toString('base64');

const now = new Date();
const submittedWIB = now.toLocaleString('id-ID', {
  timeZone: 'Asia/Jakarta',
  dateStyle: 'full',
  timeStyle: 'medium'
});

return {
  json: {
    nama: $json['Nama'],
    email: $json['Email'],
