// JSON Cleaning + Error Handling (try-catch)
const raw = $input.item.json;
const applicant = $('Code - Base64 dan Timestamp').item.json;

// Output Basic LLM Chain bisa berada di "text", "response.text", atau "output"
let aiText = raw.text ?? raw.response?.text ?? raw.output ?? '';
if (typeof aiText !== 'string') aiText = JSON.stringify(aiText);

let parsed;
let status = 'valid';
let errorMessage = '';

try {
  // 1) Hapus pembungkus markdown ```json ... ```
  let cleaned = aiText.replace(/```json/gi, '').replace(/```/g, '').trim();

  // 2) Ambil hanya bagian dari "{" pertama sampai "}" terakhir
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) {
    throw new Error('Objek JSON tidak ditemukan pada output AI');
  }
  cleaned = cleaned.slice(start, end + 1);

  // 3) Parse JSON
  parsed = JSON.parse(cleaned);

  // 4) Validasi struktur
  if (typeof parsed.ringkasan_profil !== 'string') throw new Error('Field ringkasan_profil tidak valid');
  if (!Array.isArray(parsed.skill_utama)) throw new Error('Field skill_utama harus berupa array');
  if (typeof parsed.rekomendasi !== 'string') throw new Error('Field rekomendasi tidak valid');
} catch (error) {
  status = 'fallback';
  errorMessage = error.message;
  parsed = {
    ringkasan_profil: 'Output AI tidak dapat diparse sebagai JSON valid.',
    skill_utama: [],
    rekomendasi: 'Mohon review CV secara manual. Cuplikan output AI: ' + aiText.slice(0, 300)
  };
}

const skills = parsed.skill_utama.length
  ? parsed.skill_utama.map(s => '- ' + s).join('\n')
  : '- (tidak tersedia)';

const telegramMessage =
`📄 PENGAJUAN CV BARU

👤 Nama: ${applicant.nama}
📧 Email: ${applicant.email}
💼 Posisi: ${applicant.posisi}
🕒 Waktu Pengajuan: ${applicant.submitted_at_wib}
📎 File: ${applicant.cv_filename}

📝 Ringkasan Profil:
${parsed.ringkasan_profil}

🛠 Skill Utama:
${skills}

✅ Rekomendasi:
${parsed.rekomendasi}

Status JSON: ${status}${errorMessage ? ' (' + errorMessage + ')' : ''}`;

return {
  json: {
    json_status: status,
    error_message: errorMessage,
    analysis: parsed,
    telegram_message: telegramMessage
  }
};
